window.PREP_QUIZZES = {"mcp": {"id": "mcp", "title": "MCP practice room", "description": "Protocol basics, tool contracts, authorization and production recovery. Choose one answer, check the explanation, then continue.", "reference": "Questions about version-dependent details use the 2025-11-25 protocol specification; check your actual SDK and negotiated version.", "sources": [{"title": "MCP architecture", "url": "https://modelcontextprotocol.io/docs/learn/architecture"}, {"title": "MCP 2025-11-25 authorization", "url": "https://modelcontextprotocol.io/specification/2025-11-25/basic/authorization"}, {"title": "MCP 2025-11-25 transports", "url": "https://modelcontextprotocol.io/specification/2025-11-25/basic/transports"}], "questions": [{"id": "mcp-roles", "tag": "Foundations", "prompt": "Which statement best describes an MCP host, client and server?", "options": ["The host coordinates clients, and each client communicates with a server exposing capabilities.", "Every MCP server must host an LLM.", "The client is always a browser and the server is always a database.", "The protocol replaces the application's authorization system."], "correct": 0, "explanation": "The host is the AI application. It manages client connections to servers that expose capabilities. A server need not run a model, and the application still owns authorization and orchestration.", "technical": "Separate protocol participants from deployment processes. A host can connect to multiple servers through its client components; local and remote placement do not change each participant's responsibility.", "followups": [["Can one host use several servers?", "Yes. Keep connection lifecycle, identity and capability scope clear for each server."], ["Does an MCP server have to be remote?", "No. A local subprocess can expose capabilities, while a remote service can support network clients."]]}, {"id": "mcp-primitives", "tag": "Foundations", "prompt": "How do tools, resources and prompts differ in MCP?", "options": ["They are three names for executable functions.", "Tools expose callable operations, resources expose contextual data, and prompts expose reusable interaction templates.", "Resources can always modify databases.", "Prompts grant authorization to use every tool."], "correct": 1, "explanation": "These primitives serve different roles. A resource is not automatically an action, and a prompt template is not permission to execute a tool. The host decides how to present and use exposed capabilities.", "technical": "Describe actual schemas, resource identifiers and prompt arguments rather than assuming every primitive has identical discovery or invocation behavior. Supported features depend on the selected protocol and SDK.", "followups": [["Can a read-only lookup be a tool?", "Yes. Tools can be read-only or effectful. The server must enforce the actual behavior and access policy."], ["Do templates make output safe?", "No. Validate requests, evidence and tool effects independently of template wording."]]}, {"id": "mcp-jsonrpc", "tag": "Protocol", "prompt": "Which message format underlies MCP protocol communication?", "options": ["An arbitrary unstructured chat transcript.", "SQL statements sent directly to every server.", "JSON-RPC messages with the selected transport's framing rules.", "Only binary GPU tensors."], "correct": 2, "explanation": "MCP uses JSON-RPC message structures. Transport framing, lifecycle and the supported protocol version still matter; a plain REST endpoint returning JSON is not automatically a compliant MCP server.", "technical": "Distinguish requests, responses and notifications. Preserve request IDs and valid error structures, and follow the chosen transport's content and framing requirements.", "followups": [["Does every notification need a response?", "No. Notifications differ from requests. Follow JSON-RPC and MCP semantics instead of returning ad hoc acknowledgments."], ["Is any JSON API an MCP implementation?", "No. Discovery, lifecycle, capability and transport behavior must also satisfy the implemented specification."]]}, {"id": "mcp-schema", "tag": "Tool contracts", "prompt": "An MCP tool expects a positive invoice ID, but the model supplies free-form text. What should happen?", "options": ["Execute it because the model selected the tool.", "Convert the text into SQL automatically.", "Ignore the tool schema.", "Validate the input and reject or safely repair it before execution."], "correct": 3, "explanation": "Generated arguments are untrusted input. Validate schema, meaning, ownership and permissions before accessing a resource or performing an effect. A valid JSON object alone does not establish a valid business request.", "technical": "Use a typed input contract plus server-side business rules and parameterized queries. Bound repair attempts and return useful sanitized errors without leaking secrets or internal stack traces.", "followups": [["Can schema validation replace authorization?", "No. An ID can have the correct type and still refer to another tenant's object."], ["Why bound repair attempts?", "Repeated generation can consume resources or repeat deterministic errors. Fail clearly or clarify after the budget is exhausted."]]}, {"id": "mcp-authn-authz", "tag": "Security", "prompt": "A user has a valid login token. What must the tool server still check?", "options": ["That the current identity is permitted to perform this action on this resource.", "Nothing; any signed-in user can access every resource.", "Only whether the model sounds confident.", "Whether the tool name contains the word secure."], "correct": 0, "explanation": "Authentication identifies a principal; authorization limits its actions and resources. A valid login token is not a universal access grant.", "technical": "Validate issuer/audience/expiry as appropriate, then scopes, tenant/resource ownership and current policy. Resolve trusted identity independently of model-generated tenant IDs.", "followups": [["Can the model choose a tenant_id?", "It can mention one, but trusted backend policy must resolve and authorize the actual scope."], ["Should permission be checked only at login?", "No. Check the relevant protected reads/effects and account for revocation at the required boundaries."]]}, {"id": "mcp-stdio-log", "tag": "Transport", "prompt": "A local stdio server prints debug text to stdout. Why can the client fail?", "options": ["Stdout is reserved for encrypted images.", "Non-protocol output corrupts the message stream; diagnostics belong on stderr.", "MCP never supports local servers.", "Debug logs automatically authorize the client."], "correct": 1, "explanation": "For the 2025-11-25 stdio transport, stdout carries protocol messages. Ordinary diagnostic output can break framing and parsing. Put diagnostics on stderr and keep secrets out of logs.", "technical": "Ensure libraries and startup code do not emit banners into stdout. Follow newline-delimited message framing and test the real subprocess entry point, not just a tool function in isolation.", "followups": [["Does any stderr output mean the server failed?", "No. Stderr can contain legitimate diagnostics. Inspect process status and protocol behavior too."], ["Why test the packaged entry point?", "Packaging and startup scripts can introduce logging, missing environment values or wrong working-directory assumptions."]]}, {"id": "mcp-http", "tag": "Transport", "prompt": "Which statement fits Streamable HTTP in the 2025-11-25 specification?", "options": ["Every response must be a WebSocket message.", "SSE is a separate mandatory service for every tool.", "It uses an MCP endpoint with HTTP POST/GET behavior and can return JSON or SSE under the protocol rules.", "It removes the need for origin validation."], "correct": 2, "explanation": "Streamable HTTP is not synonymous with WebSockets or an SSE-only endpoint. The selected specification defines endpoint, request, response and streaming behavior.", "technical": "Implement the actual transport negotiation, headers, message handling and origin protections for the pinned version. Do not assume a framework's generic streaming endpoint satisfies the protocol.", "followups": [["Is streaming always required for a simple result?", "No. The selected transport permits JSON responses under its rules; follow client/server capability and request semantics."], ["Can older clients behave differently?", "Yes. Pin and test protocol/SDK compatibility, including any deliberately supported legacy transport."]]}, {"id": "mcp-oauth", "tag": "Security", "prompt": "For HTTP-based MCP authorization under 2025-11-25, what role does a protected MCP server play?", "options": ["It becomes the user's password manager.", "It must receive raw passwords from every client.", "It treats any third-party token as valid for itself.", "It acts as a protected resource server and validates appropriately scoped access tokens."], "correct": 3, "explanation": "The authorization server issues tokens; the protected MCP server accepts and validates tokens intended for it. Token issuance and resource authorization are separate responsibilities.", "technical": "Follow the specified discovery and token-validation flow for the implemented version. Check audience/resource binding and scope rather than accepting a token simply because another service accepts it.", "followups": [["Must stdio use the same HTTP OAuth flow?", "The referenced version distinguishes stdio credentials from HTTP transport authorization. Follow the relevant transport's documented model."], ["Can all clients be preregistered?", "Registration approaches depend on the supported authorization deployment. Use the actual advertised and implemented mechanisms rather than assuming one flow."]]}, {"id": "mcp-injection", "tag": "Incident", "prompt": "A retrieved resource tells the agent to upload internal files to a new URL. What is the strongest boundary?", "options": ["Treat the text as untrusted data and enforce tool/resource permissions outside the model.", "Ask the model to promise it will not be tricked.", "Give the resource higher instruction priority.", "Enable every tool to maximize task completion."], "correct": 0, "explanation": "Retrieved text has no authority to grant capabilities. Behavioral prompts can help, but server-enforced access and effect controls limit actual exposure.", "technical": "Use narrow tools, approved destinations and current identity/resource checks. Separate source evidence from instructions and test indirect injection with permitted-task completion as well as blocked attacks.", "followups": [["Can a second model guarantee protection?", "No. Evaluate detector misses and false positives while retaining enforceable boundaries."], ["What if sensitive data already reached the generator?", "Prevent that with authorized retrieval. Tool controls alone cannot prevent disclosure through the generated answer."]]}, {"id": "mcp-timeout", "tag": "Incident", "prompt": "A report-creation tool times out. Is it safe to retry with a new operation ID?", "options": ["Yes, a timeout proves the server did nothing.", "No; reconcile the previous operation and use idempotent semantics before retrying.", "Yes, if the next request uses a larger model.", "Only after hiding the error from logs."], "correct": 1, "explanation": "The remote action may have completed before the response was lost. A new ID can create a duplicate effect. Reconcile the original operation and retry under a deliberate idempotency policy.", "technical": "Store durable operation identity and status, distinguish unknown from failed, and use bounded retries with deadlines. Checkpoints do not make external effects exactly once automatically.", "followups": [["What if the API has no idempotency support?", "Use durable intent/status tracking and available lookup, and escalate unresolved ambiguity rather than blindly repeating irreversible actions."], ["Does canceling the local task undo the remote effect?", "No. Remote execution can continue. Reconciliation and business compensation are separate operations."]]}, {"id": "mcp-discovery", "tag": "Tool contracts", "prompt": "A discovered tool's description says it is harmless. How should the host use that claim?", "options": ["As a cryptographic authorization proof.", "As permission to bypass review.", "As metadata to consider, while enforcing trust and access separately.", "As proof the tool can never change state."], "correct": 2, "explanation": "Descriptions and annotations are not security enforcement. The actual server behavior, trust relationship and permission policy determine whether a tool is allowed.", "technical": "Maintain a trusted registry or approved connection policy where required, validate tool schemas and expose only necessary capabilities. Reassess changes to tool definitions and dependencies.", "followups": [["Can a tool description itself carry an injection?", "Yes. Treat third-party metadata as untrusted and avoid elevating it into policy."], ["Should a capability change be invisible to users?", "Not when it meaningfully changes permissions or effects. Apply the host's approval and trust policy."]]}, {"id": "mcp-resource-cache", "tag": "Security", "prompt": "Two tenants request the same resource URI string. Can one cached result serve both automatically?", "options": ["Yes, matching text always means matching permission.", "Yes, if the cache is encrypted.", "Yes, when the model asks politely.", "Only if the cache policy proves the result is shareable under both scopes and current permissions."], "correct": 3, "explanation": "Resource identifiers alone may not capture tenant, identity, personalization or policy version. A shared cache can cross an access boundary even when it is encrypted.", "technical": "Partition permission-sensitive cache entries and revalidate where required. Include relevant resource/version/freshness and identity scope, and test revocation behavior.", "followups": [["Does a hash of the URI solve access isolation?", "No. Hashing the same insufficient key retains the same logical collision between user scopes."], ["Can public resources be cached globally?", "Yes, when they are genuinely public and freshness/version rules are correct. The policy must establish that property."]]}, {"id": "mcp-error", "tag": "Development", "prompt": "A tool fails because a required field is absent. Which response is most useful?", "options": ["A sanitized, actionable validation error without executing the tool.", "A fabricated success result.", "An unrestricted production stack trace with credentials.", "An infinite automatic retry loop."], "correct": 0, "explanation": "The client needs enough information to correct the request or clarify the missing input. Do not claim success, leak internals or repeat a deterministic failure without a bound.", "technical": "Distinguish protocol failures, validation problems and application/tool errors according to the selected SDK and protocol. Keep correlation IDs for diagnosis without exposing secrets.", "followups": [["Should every tool error become a protocol error?", "No. Follow the relevant tool-result/error conventions; protocol validity and business failure are different concerns."], ["When should the host ask the user?", "When required information cannot be inferred safely from trusted state or permitted sources."]]}, {"id": "mcp-progress", "tag": "Production", "prompt": "A long-running MCP operation sends progress updates. What should monitoring still enforce?", "options": ["No limits as long as a heartbeat exists.", "Per-step and whole-operation deadlines, cancellation semantics and terminal outcomes.", "Only the total number of characters streamed.", "That all tools run in the browser."], "correct": 1, "explanation": "Progress is not completion. A healthy heartbeat can accompany an endless loop or stalled business task. Deadlines and terminal states keep the workflow bounded.", "technical": "Correlate operation/run IDs, record the last completed stage and distinguish waiting for approval from active execution. Cancellation must not be mistaken for guaranteed reversal of remote effects.", "followups": [["What if a legitimate job exceeds the deadline?", "Use an explicit async/status design with an appropriate budget, not an unbounded synchronous request."], ["Should retries reset the whole deadline?", "Not automatically. A total retry/time budget prevents work from running indefinitely through repeated attempts."]]}, {"id": "mcp-revoke", "tag": "Incident", "prompt": "A user's access is revoked while an agent is paused. What happens on resume?", "options": ["The old checkpoint preserves access forever.", "The model decides whether revocation matters.", "Recheck current authorization before protected work and delivery.", "Send cached confidential content because retrieval happened earlier."], "correct": 2, "explanation": "A checkpoint preserves execution history, not permanent permission. Revalidate protected reads, effects and delivery under current policy, including saved evidence.", "technical": "Bind thread ownership to authenticated identity and track evidence provenance. Stop or quarantine state that no longer fits scope and audit the decision.", "followups": [["Can deleting the checkpoint undo a prior disclosure?", "No. Delivered responses, logs and caches have separate lifecycle controls."], ["Why check delivery as well as retrieval?", "Permission can change between retrieval and an eventual background result reaching the user."]]}, {"id": "mcp-rest", "tag": "Architecture", "prompt": "MCP versus REST: which comparison is most accurate?", "options": ["MCP makes all HTTP APIs obsolete.", "REST APIs can never back MCP tools.", "MCP is a model and REST is a database.", "MCP standardizes AI-facing capability interaction; a server can wrap existing APIs while preserving their access rules."], "correct": 3, "explanation": "MCP and ordinary HTTP APIs address different interface conventions. A server may adapt an existing service; the backend remains responsible for business correctness and permissions.", "technical": "Define an adapter boundary with typed inputs, stable errors, authentication propagation appropriate to each resource and versioned contracts. Do not blindly pass arbitrary credentials through a proxy.", "followups": [["Should every API endpoint be exposed as a tool?", "No. Expose the narrow task capabilities needed, with suitable permission and effect controls."], ["Does an adapter require rewriting the entire backend?", "No. It can wrap existing services behind a clear SDK/interface boundary if the contracts are compatible."]]}, {"id": "mcp-version", "tag": "Development", "prompt": "A client works with one SDK version but fails after a server upgrade. What do you inspect first?", "options": ["Negotiated protocol/capabilities, transport behavior and changed input/output contracts.", "Only the GPU clock speed.", "Whether users memorized tool names.", "The number of decorative UI animations."], "correct": 0, "explanation": "Compatibility includes lifecycle, transport, capabilities and schemas. Pin supported versions and reproduce the actual client/server exchange before changing unrelated infrastructure.", "technical": "Keep a compatibility matrix, contract tests and safe rollout/rollback. Do not assume every example written for an older transport or authorization revision applies unchanged.", "followups": [["Should unknown capabilities be silently invented?", "No. Follow discovery/negotiation behavior and fail or degrade deliberately when a required capability is unavailable."], ["What should a regression test exercise?", "The packaged client/server lifecycle and real message contracts, including errors and authorization boundaries."]]}, {"id": "mcp-origin", "tag": "Security", "prompt": "Why validate Origin on a local HTTP MCP service?", "options": ["To identify the LLM's temperature.", "To help prevent malicious web origins from driving requests through DNS rebinding or cross-origin paths.", "To replace all access tokens permanently.", "To make stdout logs prettier."], "correct": 1, "explanation": "Origin checks are an important HTTP transport boundary, especially for local services. They complement authentication and safe binding; they do not replace authorization.", "technical": "Use trusted allowed origins, bind local services appropriately and follow the selected transport specification's required handling. Do not treat arbitrary Host/Origin values supplied by an attacker as proof of trust.", "followups": [["Should local services bind to every network interface by default?", "Not without a deliberate need and controls. Loopback limits exposure for local-only use."], ["Is Origin an authentication credential?", "No. It is one request-context signal; non-browser clients and application permissions require proper identity controls."]]}, {"id": "mcp-test", "tag": "Testing", "prompt": "Which MCP test plan best reflects production readiness?", "options": ["Only verify the happy-path tool description.", "Only check that the server starts.", "Test contracts, denied access, malformed inputs, timeouts, recovery and compatibility.", "Use successful demos as the entire evaluation set."], "correct": 2, "explanation": "A production interface must handle permitted tasks and failure/security cases. A successful demonstration cannot prove resilience, scope isolation or compatibility.", "technical": "Include integration tests across the real transport, tenant/resource boundaries, bounded retries and ambiguous side effects. Track task success together with latency, unauthorized effects and recovery behavior.", "followups": [["What should an authorization test try?", "Access another user's resource, supply forged scope and attempt revoked access. The server must reject the actual read/effect."], ["Why test timeout recovery?", "It exposes duplicate effects and unknown outcomes that simple happy-path tests do not reveal."]]}, {"id": "mcp-least-privilege", "tag": "Architecture", "prompt": "An assistant needs to summarize invoices. Which tool design is preferable?", "options": ["A shell tool with unrestricted network and file access.", "A database administrator credential exposed to the model.", "A tool that runs arbitrary user-provided SQL as an owner.", "A narrow authorized invoice-read capability returning only required fields."], "correct": 3, "explanation": "Narrow capabilities reduce the consequences of model mistakes and injected instructions. The tool should enforce the current user's permitted invoices and minimize returned sensitive data.", "technical": "Prefer task-oriented read APIs with parameter validation, row/resource scope, audit and appropriate limits. Expand capability only for a demonstrated requirement with a matching permission model.", "followups": [["What if a new task needs writes?", "Add a separately scoped effectful capability with explicit business validation and any required approval, rather than broadening every read tool."], ["Can read-only tools still leak data?", "Yes. Unauthorized reading and overbroad responses can expose sensitive information even without modifying anything."]]}]}};
